const fs=require('fs'),path=require('path');
const files=JSON.parse("{\"apps/api/src/copilot.ts\":\"\",\"apps/api/src/llm.ts\":\"\",\"apps/api/src/config.ts\":\"\",\"apps/api/src/app.ts\":\"\",\"apps/api/test/copilot.test.ts\":\"\",\"apps/api/README.md\":\"\",\"apps/web/lib/types.ts\":\"\",\"apps/web/components/CopilotDrawer.tsx\":\"\",\"apps/web/components/TopBar.tsx\":\"\",\"apps/web/app/page.tsx\":\"\",\"README.md\":\"\",\".env.example\":\"\"}");
if(!fs.existsSync('package.json')||!fs.existsSync('apps')){console.log('Run this inside the greenwave-os folder (the one with package.json).');process.exit(1);}
